  function addProduct(){if(!editable())return;setMission(c=>({...c,produtos:[...c.produtos,{id:id("produto"),nome:"",dose:0,unidade:"mL/ha"}]}));invalidateCore()} function removeProduct(pid:string){if(!editable())return;setMission(c=>({...c,produtos:c.produtos.length<=1?c.produtos:c.produtos.filter(p=>p.id!==pid)}));invalidateCore()}
