  async function releaseOrder(){if(!mission.ordemServicoId)return true;try{const r=await fetch("/api/dronegestor/cadastros",{method:"PATCH",headers:{"Content-Type":"application/json"},body:JSON.stringify({type:"os",entityId:mission.ordemServicoId,data:{status:"aberta"}}),cache:"no-store"});return r.ok}catch{return false}}
  async function resetMission(){if(operationStarted)return flash("Existe uma operação em andamento. Pause/retome e conclua antes de trocar de missão.");if(!frozen&&mission.ordemServicoId&&!(await releaseOrder()))return flash("Não foi possível liberar a OS atual. Conecte-se à internet e tente novamente antes de trocar de missão.");if(!window.confirm(frozen?"Arquivar esta missão no aparelho e iniciar uma nova aplicação?":"Limpar a missão atual e iniciar uma nova aplicação?"))return;const b=normalizeMission(null);setMission(b);setCalibration(blankCalibration);setChecklist(blankChecklist);setInsightAccepted(false);setRiskAccepted(false);setProgressHa(0);setPaused(false);setOccurrences([]);setFinalSaved(false);setPendingCurrent(false);localStorage.removeItem(KEYS.operationId);localStorage.removeItem(KEYS.lastFinalized);localStorage.removeItem(KEYS.startedAt);localStorage.removeItem(KEYS.finalizedAt);go("nova")}
  async function patchOs(status:string){if(!mission.ordemServicoId)return true;const r=await fetch("/api/dronegestor/cadastros",{method:"PATCH",headers:{"Content-Type":"application/json"},body:JSON.stringify({type:"os",entityId:mission.ordemServicoId,data:{status}}),cache:"no-store"});const p=await r.json().catch(()=>null);if(!r.ok){flash(p?.error||"Não foi possível atualizar a OS.");return false}return true}
