  function recordTankArea(){if(paused)return flash("Retome a operação antes de registrar área executada.");const remaining=Math.max(0,mission.area-progressHa);const text=window.prompt(`Informe a área REAL executada neste tanque (ha). Restante planejado: ${fmt(remaining,2)} ha.`,String(round(Math.min(calc.areaTank,remaining),2)));if(text===null)return;const value=n(text.replace(",","."));if(value<=0||value>remaining+0.01)return flash("Informe uma área válida, maior que zero e não superior ao restante planejado.");const next=Math.min(mission.area,round(progressHa+value,2));setProgressHa(next);flash(next>=mission.area?"100% da área planejada registrada.":`Área real acumulada: ${fmt(next,2)} ha.`)}
  function correctProgress(){const text=window.prompt(`Informe o total REAL já executado (0 a ${fmt(mission.area,2)} ha).`,String(progressHa));if(text===null)return;const value=n(text.replace(",","."));if(value<0||value>mission.area+0.01)return flash("Total de área inválido.");setProgressHa(round(Math.min(value,mission.area),2));flash("Área real acumulada corrigida.")}
